<script lang="ts">
    import { onDestroy } from "svelte"
    import TrainingBody from "./TrainingBody.svelte"
    import { dayKey } from "@/lib/center"
    import { trainingId, trainingVolume, type TrainingData } from "@/lib/training"
    import { statsSessions, muscleStats, trainingTotals, chartPoints, moodLabels, validMood, relativeStrength } from "@/lib/trainingStats"
    export let data: TrainingData
    export let disabled = false
    export let onSave: (data: TrainingData) => Promise<boolean>
    export let selected = ""
    export let onProfile:()=>void=()=>{}
    let period = 30, strengthExercise = "bench"
    let height: number | undefined = data.profile?.heightCm ?? undefined
    let weight: number | undefined, measurementDate = dayKey(new Date()), notice = "", error = "", busy = false
    let timer: ReturnType<typeof setTimeout>
    onDestroy(() => clearTimeout(timer))
    const today = dayKey(new Date())
    const positions = [
        {group:"Грудь",x:27,y:22,w:21,h:8}, {group:"Спина",x:73,y:29,w:21,h:15},
        {group:"Плечи",x:13,y:20,w:9,h:9}, {group:"Бицепс",x:12,y:29,w:7,h:9},
        {group:"Трицепс",x:88,y:29,w:7,h:9}, {group:"Пресс",x:27,y:33,w:13,h:12},
        {group:"Ноги",x:20,y:57,w:11,h:20},
    ]
    $: sessions = statsSessions(data,Number(period))
    $: totals = trainingTotals(sessions)
    $: muscles = muscleStats(sessions)
    $: maxSets = Math.max(1,...muscles.map(item=>item.sets))
    $: allMeasurements = [...(data.profile?.measurements || [])].sort((a,b)=>a.date.localeCompare(b.date))
    $: latest = allMeasurements.filter(item=>item.date<=today).at(-1)
    $: cutoff = (()=>{const date=new Date();date.setDate(date.getDate()-Number(period)+1);return dayKey(date)})()
    $: measurements = allMeasurements.filter(item=>item.date<=today && (!Number(period) || item.date>=cutoff))
    $: weightChart = chartPoints(measurements.map(item=>({date:item.date,value:item.weight})))
    $: weightChange = measurements.length>1 ? measurements[measurements.length-1].weight-measurements[0].weight : null
    $: volumeMax = Math.max(1,...sessions.map(trainingVolume))
    $: volumeRows = sessions.slice(-12)
    $: moodSessions = sessions.filter(item=>validMood(item.mood))
    $: selectedSets = muscles.find(item=>item.group===selected)?.sets || 0
    $: strengthSession = [...sessions].reverse().find(session=>relativeStrength(session,strengthExercise)!==null)
    $: strength = strengthSession ? relativeStrength(strengthSession,strengthExercise) : null
    function count(group:string) { return muscles.find(item=>item.group===group)?.sets || 0 }
    function shortDate(value:string) { return new Date(value.length===10?`${value}T12:00`:value).toLocaleDateString("ru-RU",{day:"numeric",month:"short"}) }
    async function saveProfile() {
        if(disabled || busy) return
        error="";notice=""
        if(height!==undefined && (!Number.isFinite(height)||height<50||height>250)) {error="Укажите рост от 50 до 250 см или оставьте поле пустым.";return}
        if(weight!==undefined && (!Number.isFinite(weight)||weight<1||weight>500)) {error="Укажите вес от 1 до 500 кг или оставьте поле пустым.";return}
        const parsedDate = new Date(`${measurementDate}T12:00`)
        if(!/^\d{4}-\d{2}-\d{2}$/.test(measurementDate)||Number.isNaN(parsedDate.getTime())||dayKey(parsedDate)!==measurementDate||measurementDate>today) {error="Укажите корректную дату измерения не позже сегодняшней.";return}
        const measurements = weight===undefined ? allMeasurements : [...allMeasurements.filter(item=>item.date!==measurementDate),{id:trainingId(),date:measurementDate,weight}]
        busy=true
        try {
            if(await onSave({...data,profile:{...data.profile,heightCm:height??null,measurements}})) {
                weight=undefined;notice="Профиль сохранён";clearTimeout(timer);timer=setTimeout(()=>notice="",2000)
            } else error="Не удалось сохранить профиль. Повторите попытку."
        } catch {error="Не удалось сохранить профиль. Повторите попытку."}
        finally {busy=false}
    }
    async function removeMeasurement(id:string) {
        if(disabled||busy||!confirm("Удалить это измерение веса? Значения в истории тренировок останутся без изменений."))return
        busy=true;error=""
        try {if(!await onSave({...data,profile:{...data.profile,heightCm:data.profile?.heightCm??null,measurements:allMeasurements.filter(item=>item.id!==id)}}))error="Не удалось удалить измерение."}
        catch {error="Не удалось удалить измерение."} finally {busy=false}
    }
</script>

<section class="stats-dashboard" aria-label="Статистика и профиль тренировок">
    <header><div><p class="eyebrow">JARVIS / BODY & PERFORMANCE</p><h3>Картина твоего прогресса</h3><p class="subtitle">Тренировки, тело и настроение — из твоих записей.</p></div><select aria-label="Период статистики тренировок" bind:value={period}><option value={7}>7 дней</option><option value={30}>30 дней</option><option value={0}>Всё время</option></select></header>
    <div class="scorecards"><div><span>Тренировок</span><strong>{totals.sessions}</strong><small>завершено за период</small></div><div><span>Рабочих подходов</span><strong>{totals.sets}</strong><small>без разминки</small></div><div><span>Тренировочный объём</span><strong>{totals.volume.toLocaleString("ru-RU")}<em>кг</em></strong><small>сумма веса × повторов</small></div><div><span>Настроение</span><strong>{totals.mood===null?"—":totals.mood.toFixed(1)}<em>{totals.mood===null?"":"/ 5"}</em></strong><small>{totals.moodCount} тренировок с оценкой</small></div></div>
    <button class="profile-link" on:click={onProfile}>Изменить рост, вес и другие данные → Мои параметры</button>
    <div class="body-layout"><div class="panel body-panel"><TrainingBody bind:selected counts={muscles} exercises={data.exercises} metric="Рабочие подходы за выбранный период" caption="Только завершённые тренировки, без разминки. Подсветка не измеряет восстановление." /></div>
    <div class="profile-column">
    <div class="panel"><div class="section-title"><div><p class="eyebrow">РАСПРЕДЕЛЕНИЕ</p><h4>Подходы по группам</h4></div><small>{totals.sets} всего</small></div>{#if !muscles.length}<p class="empty">Заверши первую тренировку — здесь появятся реальные значения.</p>{/if}{#each muscles as item}<button class="muscle-row" class:selected={selected===item.group} aria-pressed={selected===item.group} on:click={()=>selected=selected===item.group?"":item.group}><span>{item.group}</span><i><b style={`width:${item.sets/maxSets*100}%`}></b></i><strong>{item.sets}</strong><small>{totals.sets?Math.round(item.sets/totals.sets*100):0}%</small></button>{/each}</div>
    <div class="panel relative"><p class="eyebrow">С УЧЁТОМ ВЕСА ТЕЛА</p><h4>Относительный расчётный 1RM</h4><select bind:value={strengthExercise} aria-label="Упражнение для относительной силы">{#each data.exercises as exercise}<option value={exercise.id}>{exercise.name}</option>{/each}</select><strong>{strength===null?"—":`${strength.toFixed(2)} ×`}</strong><small>{strengthSession?`${shortDate(strengthSession.startedAt)} · вес тела ${strengthSession.bodyWeight} кг`:"Нужна завершённая тренировка с весом тела и подходом на 1–10 повторов."}</small><p class="footnote">Расчётный 1RM / вес тела на момент тренировки. Это оценка, а не подтверждённый максимум или оценка здоровья.</p></div></div></div>
    <div class="chart-grid"><div class="panel weight-chart"><div class="section-title"><div><p class="eyebrow">ИЗМЕНЕНИЯ ТЕЛА</p><h4>История веса</h4></div><span class="badge">{weightChange===null?"—":`${weightChange>0?"+":""}${weightChange.toFixed(1)} кг`}</span></div><small>Измерения за выбранный период · кг · шкала приближена к диапазону данных</small>
        {#if !measurements.length}<p class="empty">Добавь измерение веса в профиль. График не заполняется примерными числами.</p>{:else if measurements.length<3}<div class="measurement-cards">{#each measurements as item}<div><strong>{item.weight} кг</strong><small>{shortDate(item.date)}</small></div>{/each}</div><p class="footnote">Для линии нужно минимум 3 измерения. Пока показаны точные записи.</p>{:else}<svg viewBox="0 0 560 195" role="img" aria-label="График веса тела по сохранённым измерениям"><title>Вес тела, кг</title>{#each [weightChart.low,(weightChart.low+weightChart.high)/2,weightChart.high] as tick}<line x1="48" x2="512" y1={150-(tick-weightChart.low)/(weightChart.high-weightChart.low)*112} y2={150-(tick-weightChart.low)/(weightChart.high-weightChart.low)*112} stroke="#29494f" stroke-dasharray="3 5"/><text x="40" y={154-(tick-weightChart.low)/(weightChart.high-weightChart.low)*112} text-anchor="end" fill="#91abb1" font-size="11">{tick.toFixed(1)}</text>{/each}<path d={weightChart.path} fill="none" stroke="#60f3e9" stroke-width="3"/>{#each weightChart.points as point,index}<circle cx={point.x} cy={point.y} r="4" fill="#60f3e9"><title>{shortDate(point.date)}: {point.value} кг</title></circle>{#if index===0||index===weightChart.points.length-1}<text x={point.x} y="181" text-anchor="middle" fill="#91abb1" font-size="11">{shortDate(point.date)}</text>{/if}{/each}</svg>{/if}
        <details><summary>Все измерения · {allMeasurements.length}</summary><div class="measurements">{#each [...allMeasurements].reverse() as item}<div><span>{shortDate(item.date)}</span><strong>{item.weight} кг</strong></div>{/each}</div></details>
    </div><div class="panel"><p class="eyebrow">РАБОТА В ЗАЛЕ</p><h4>Объём по тренировкам</h4><small>До 12 последних завершённых тренировок за период · кг, вес × повторы</small>{#if !volumeRows.length}<p class="empty">Пока нет завершённых тренировок.</p>{:else}<svg viewBox="0 0 560 195" role="img" aria-label="Столбчатый график тренировочного объёма"><title>Объём каждой тренировки, кг</title>{#each [0,volumeMax/2,volumeMax] as tick}<line x1="48" x2="535" y1={155-tick/volumeMax*120} y2={155-tick/volumeMax*120} stroke="#29494f" stroke-dasharray="3 5"/><text x="40" y={159-tick/volumeMax*120} text-anchor="end" fill="#91abb1" font-size="10">{Math.round(tick)}</text>{/each}{#each volumeRows as item,index}<rect x={62+index*464/volumeRows.length} y={155-trainingVolume(item)/volumeMax*120} width={Math.min(36,360/volumeRows.length)} height={trainingVolume(item)/volumeMax*120} fill="#60f3e9" rx="3"><title>{item.name} · {shortDate(item.startedAt)}: {trainingVolume(item)} кг</title></rect>{#if volumeRows.length<7||index%2===0}<text x={62+index*464/volumeRows.length+Math.min(36,360/volumeRows.length)/2} y="181" text-anchor="middle" fill="#91abb1" font-size="10">{shortDate(item.startedAt)}</text>{/if}{/each}</svg>{/if}<p class="footnote">Объём зависит от упражнения и введённого веса; не является единственной мерой силы. Нулевой объём возможен при упражнениях без отягощения.</p></div></div>
    <div class="panel mood-panel"><div class="section-title"><div><p class="eyebrow">КАК ТЫ СЕБЯ ЧУВСТВОВАЛ</p><h4>Настроение перед тренировками</h4></div><small>{moodSessions.length} оценок за период</small></div>{#if !moodSessions.length}<p class="empty">Укажи настроение при запуске тренировки. В старых записях отсутствующие оценки останутся пустыми.</p>{:else}<div class="mood-history">{#each moodSessions.slice(-12) as item}<div title={`${item.name}: ${moodLabels[item.mood||0]}`}><span class="mood-score">{item.mood}<small>/5</small></span><strong>{moodLabels[item.mood||0]}</strong><span>{shortDate(item.startedAt)}</span></div>{/each}</div>{/if}<p class="footnote">Самооценка, не диагноз и не процент восстановления. Рост, вес и настроение не используются для автоматического назначения нагрузки.</p></div>
</section>

<style>
    .stats-dashboard{--accent:#60f3e9;--line:#28494f;--muted:#91abb1;color:#eaffff;font-family:"Manrope Variable",sans-serif}header,.section-title{display:flex;align-items:center;justify-content:space-between;gap:.7rem;margin-bottom:1rem}.eyebrow{margin:0;color:var(--accent);font-size:.58rem;letter-spacing:.14em;font-weight:800}h3{font-size:1.35rem;letter-spacing:-.035em;margin:.4rem 0}h4{font-size:.9rem;margin:.4rem 0}.subtitle{color:var(--muted);font-size:.7rem;margin:0}.scorecards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.6rem;margin-bottom:1rem}.scorecards>div{padding:.85rem;border:1px solid var(--line);border-radius:10px;background:linear-gradient(125deg,#1c494947,#0d1b20);display:flex;flex-direction:column;gap:.4rem}.scorecards span{font-size:.61rem;color:#b4ced0}.scorecards strong{font-size:1.45rem;font-variant-numeric:tabular-nums;letter-spacing:-.04em}.scorecards em,.body-numbers em{font-style:normal;font-size:.65rem;color:var(--muted);margin-left:.3rem}small{font-size:.6rem;color:var(--muted);line-height:1.6}.panel{padding:1rem;background:linear-gradient(145deg,#163a3d55,transparent 65%),#0b1b20;border:1px solid var(--line);border-radius:13px;min-width:0}.body-layout{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:.8rem;align-items:start}.profile-column{display:flex;flex-direction:column;gap:.8rem}.body-scene{position:relative;overflow:hidden;border-radius:10px;border:1px solid #1c444d;background:#071a22}.body-scene img{display:block;width:100%;height:auto;opacity:.84}.body-zone{position:absolute;transform:translate(-50%,-50%);border:1px solid transparent;background:transparent;border-radius:40%;padding:0;transition:background .2s,box-shadow .2s}.body-zone.highlighted{background:rgba(69,240,218,calc(.08 + var(--intensity)*.22));box-shadow:0 0 15px #60f3e91c}.body-zone.chosen{border-color:#d5fff9;background:#60f3e94d;box-shadow:0 0 25px #60f3e955}.body-zone span{display:grid;place-items:center;margin:auto;background:#062b35e6;border:1px solid #54cfc9;border-radius:50%;width:22px;height:22px;font-size:.6rem;color:#b2fff4}.body-zone:not(.highlighted) span{opacity:.55}.body-caption{position:absolute;bottom:.75rem;left:0;right:0;display:flex;justify-content:space-around;pointer-events:none;color:#a4ebed;font-size:.55rem;letter-spacing:.13em}.body-result{display:flex;align-items:center;gap:.7rem;margin-top:.9rem}.body-result strong{font-size:1.7rem;color:var(--accent)}.body-result span{font-size:.7rem;color:#b4ced0}.footnote{font-size:.58rem;color:var(--muted);line-height:1.65;margin:.8rem 0 0}.badge{padding:.3rem .55rem;border:1px solid #357274;background:#123638;color:#a9fff0;border-radius:6px;font-size:.6rem;white-space:nowrap}.body-numbers{display:flex;gap:1rem;margin:1rem 0}.body-numbers>div{flex:1;display:flex;flex-direction:column;gap:.2rem}.body-numbers strong{font-size:1.7rem}.body-numbers small{font-size:.62rem}form{display:flex;flex-direction:column;gap:.6rem;margin-bottom:.7rem}.form-grid{display:flex;gap:.5rem}.form-grid label{flex:1;min-width:0}label{display:flex;flex-direction:column;gap:.3rem;font-size:.65rem;color:#a4bdc0}button,input,select{font:600 .68rem "Manrope Variable",sans-serif;border:1px solid var(--line);border-radius:7px;padding:.5rem;background:#102a30;color:#eaffff;box-sizing:border-box}input{width:100%;min-width:0;color-scheme:dark}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.primary{background:#159f9f;color:#061e23;border-color:#60f3e9;font-weight:800;min-height:38px}.muscle-row{display:flex;align-items:center;gap:.45rem;width:100%;padding:.65rem .35rem;border:0;border-bottom:1px solid #203e43;border-radius:0;background:transparent;text-align:left}.muscle-row>span{width:67px;font-size:.62rem}.muscle-row>i{display:block;flex:1;height:6px;background:#203a40;border-radius:5px;overflow:hidden}.muscle-row b{display:block;height:100%;background:#60f3e9}.muscle-row>strong{width:22px;text-align:right;font-size:.68rem}.muscle-row>small{width:32px;text-align:right}.muscle-row.selected{background:#164247}.relative select{width:100%;margin:.4rem 0}.relative>strong{display:block;margin:.7rem 0 .3rem;font-size:1.8rem;color:var(--accent)}.chart-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem;margin-top:.8rem}.chart-grid svg{display:block;width:100%;margin-top:.7rem}.empty{color:var(--muted);font-size:.72rem;line-height:1.7;padding:1.2rem 0}.measurement-cards{display:flex;gap:.7rem;margin:1.2rem 0}.measurement-cards>div{display:flex;flex-direction:column;gap:.3rem;flex:1;padding:.8rem;background:#122e35;border-radius:7px}.measurement-cards strong{font-size:1.1rem}details{margin-top:.8rem}summary{font-size:.62rem;color:var(--accent);cursor:pointer}.measurements{max-height:220px;overflow:auto}.measurements>div{display:flex;align-items:center;gap:.5rem;padding:.4rem 0;border-bottom:1px solid var(--line);font-size:.65rem}.measurements strong{margin-left:auto}.measurements button{padding:.15rem .4rem}.mood-panel{margin-top:.8rem}.mood-history{display:flex;gap:.5rem;overflow-x:auto;padding:.4rem 0}.mood-history>div{display:flex;flex-direction:column;align-items:center;gap:.3rem;min-width:88px;padding:.7rem;border:1px solid var(--line);background:#10282e;border-radius:8px}.mood-score{font-size:1.35rem;font-weight:800;color:var(--accent)}.mood-score small{font-size:.65rem}.mood-history strong{font-size:.58rem}.mood-history>div>span:last-child{font-size:.57rem;color:var(--muted)}.success{font-size:.65rem;color:#a6ffdf}.error{font-size:.65rem;color:#ffc4c4}@media(max-width:1000px){.body-layout{grid-template-columns:1fr}.body-scene{max-width:360px;margin:auto}.chart-grid{grid-template-columns:1fr}.scorecards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){header{align-items:flex-start;flex-direction:column}.scorecards strong{font-size:1.2rem}.section-title{flex-wrap:wrap}.form-grid{flex-direction:column}}@media(prefers-reduced-motion:reduce){.body-zone{transition:none}}
    .body-layout{grid-template-columns:1fr}.profile-column{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem}.profile-link{margin-bottom:1rem}.body-panel{width:100%;box-sizing:border-box}@media(max-width:600px){.profile-column{grid-template-columns:1fr}}
</style>
